WITH roster AS ( SELECT DISTINCT a.expert_id AS agent_id FROM hive.care.expert_performance_metrics a WHERE CAST(a."date" AS DATE) BETWEEN DATE '2026-07-18' AND DATE '2026-08-28' AND LOWER(a.icp_client) IN ( 'mob-at&t','mob-verizon','pss-at&t','pss-at&t nac','pss-verizon','xbox','mcafee' ) ), dedup AS ( SELECT b.partner_agent_id AS agent_id, CAST(b."created_at" AS DATE) AS evt_date, b.template_questions_name AS scorecard_name, b.template_questions_phrase AS behavior_raw, MAX(CAST(b.response_obtainedscore AS DOUBLE)) AS response_obtainedscore, MAX(CAST(b.template_questions_score AS DOUBLE)) AS template_questions_score FROM hive.care.l3_asurion_observe_autoqa_evaluations b JOIN roster r ON r.agent_id = b.partner_agent_id WHERE CAST(b."created_at" AS DATE) BETWEEN DATE '2026-07-18' AND DATE '2026-08-28' AND b.template_questions_name IN ( 'HEROES Auto Scorecard','HEROES Auto QA Reporting - VZW','Customer Sentiment Scorecard V1' ) GROUP BY b.partner_agent_id, CAST(b."created_at" AS DATE), b.template_questions_name, b.template_questions_phrase, b.meeting_id ) SELECT d.agent_id AS agent_id, CAST(date_add('day', 4, date_trunc('week', d.evt_date)) AS DATE) AS week_ending, 'all' AS call_type, d.scorecard_name AS scorecard_name, CASE WHEN d.scorecard_name IN ('HEROES Auto Scorecard', 'HEROES Auto QA Reporting - VZW') THEN replace(TRIM(regexp_replace(regexp_replace(d.behavior_raw, '^\s*(\d+~|_)', ''), '\s*:\s*$', '')), ' & ', ' and ') ELSE d.behavior_raw END AS behavior, SUM(COALESCE(d.response_obtainedscore, 0.0)) AS numerator, SUM(COALESCE(d.template_questions_score, 0.0)) AS denominator, CASE WHEN SUM(COALESCE(d.template_questions_score, 0.0)) = 0 THEN NULL ELSE SUM(COALESCE(d.response_obtainedscore, 0.0)) / SUM(COALESCE(d.template_questions_score, 0.0)) END AS calc FROM dedup d GROUP BY 1, 2, 3, 4, 5
